def find_divider(grid):
    """A row or column index, with axis, that is one constant nonzero color (the separator)."""
    for j in range(len(grid[0])):
        col = {r[j] for r in grid}
        if len(col) == 1 and 0 not in col:
            return ('col', j)
    for i, row in enumerate(grid):
        if len(set(row)) == 1 and 0 not in row:
            return ('row', i)
    return None

def split(grid):
    """Split a grid at its constant nonzero divider line into the two patterns on either side."""
    kind, k = find_divider(grid)
    if kind == 'col':
        return [r[:k] for r in grid], [r[k + 1:] for r in grid]
    return grid[:k], grid[k + 1:]

def transform(grid):
    a, b = split(grid)
    return overlap(a, b)
''')
